def main():
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    foods = []
    for row in FOODS:
        fid, group, k, p, na, pr, add, water, ar, fr, en, es = row
        foods.append({"id": fid, "g": group, "n": {"ar": ar, "fr": fr, "en": en, "es": es},
                      "k": k, "p": p, "na": na, "pr": pr, "add": add, "water": water})
    dishes = [{"id": d[0], "k": d[1], "p": d[2], "na": d[3], "fl": d[4], "n": d[5], "tip": d[6]} for d in DISHES]
    ids = [f["id"] for f in foods] + [d["id"] for d in dishes]
    assert len(ids) == len(set(ids)), "duplicate ids"
    with open(os.path.join(root, "app/src/main/assets/foods.json"), "w", encoding="utf-8") as f:
        json.dump({"foods": foods, "dishes": dishes}, f, ensure_ascii=False, indent=1)
    print(len(foods), "foods,", len(dishes), "dishes")

if __name__ == "__main__":
    main()
